styl:
.b-new-hero-17 u + .body .gmail-blend-screen {  background: #000;
  mix-blend-mode: screen;  }
.b-new-hero-17 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.bgr-image.b-new-hero-17 {  background: url("https://fsms.quadcode.com/storage/public/d6/q2/65jursrq72d918ug/2-1-5-back.png") center top no-repeat;
  background-size: cover;
  background-color: #000;  }
.brad-full.b-new-hero-17 {  border-radius: 32px !important;  }
.b-new-hero-17 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 42px;
  line-height: 52px;
  color: #f9f9f9;
  word-break: break-word;
  padding-right: 30px;  }
@media screen and (max-width: 600px) {
  .b-new-hero-17 .white-title {  font-size: 26px !important;
    line-height: 32px !important;  }
}
.b-new-hero-17 .white-text {  font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;
  padding-right: 20px;  }
@media screen and (max-width: 600px) {
  .b-new-hero-17 .white-text {  padding-right: 0 !important;  }
}
.b-new-hero-17 .pb16 {  padding-bottom: 16px;  }
.b-new-hero-17 u+.body .gmail-blend-screen {  background:#000;mix-blend-mode:screen  }
