.b-new-hero-17 .bgr, .bgr-image.b-new-hero-17 {  background-size:cover  }
.bgr-image.b-new-hero-17 {  background:url(https://fsms.quadcode.com/storage/public/d6/q2/65jursrq72d918ug/2-1-5-back.png) center top no-repeat;background-color:#000  }
